#include "ModularDsp.h"
#include "LoudnessMeter.h"
#include <array>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <vector>
using Audio=std::array<std::vector<float>,2>;
Audio source(int rate){Audio x;for(auto& c:x)c.resize(rate*5);for(int i=0;i<rate*5;++i){const double t=double(i)/rate;const float pulse=i%(rate/4)<180?std::exp(-float(i%(rate/4))/45.f)*.55f:0;const float body=.18f*std::sin(6.283185307179586*83*t)+.09f*std::sin(6.283185307179586*713*t)+.04f*std::sin(6.283185307179586*4103*t);x[0][i]=body+pulse;x[1][i]=body*.83f+pulse*.91f+.025f*std::sin(6.283185307179586*1307*t);}return x;}
struct Render{Audio audio;float maxGr=0,maxPunch=0;};Render render(const Audio& in,int rate,int mode){Render out{in};masterlab::DynamicsSettings c;c.enabled=mode>0;c.threshold=-27;c.ratio=5;c.attack=12;c.release=120;c.knee=4;if(mode>=2)c.intensity=2;if(mode==3)c.punch=80;masterlab::SmartCompressor d;d.settings(c);d.prepare(rate);for(int offset=0;offset<int(in[0].size());offset+=257){const int n=std::min(257,int(in[0].size())-offset);d.process(out.audio[0].data()+offset,out.audio[1].data()+offset,n);out.maxGr=std::max(out.maxGr,d.read().reduction);out.maxPunch=std::max(out.maxPunch,d.read().punch);}return out;}
struct Metrics{double lufs=-120,peak=0,rms=0,crest=0;};Metrics measure(const Audio& a,int rate){masterlab::LoudnessMeter meter;meter.prepare(rate);Metrics m;double energy=0;size_t n=0;for(size_t i=0;i<a[0].size();++i){meter.push(a[0][i],a[1][i]);if(i>=size_t(rate)){for(int c=0;c<2;++c){m.peak=std::max(m.peak,std::abs(double(a[c][i])));energy+=double(a[c][i])*a[c][i];++n;}}}m.lufs=meter.read().integrated;m.rms=std::sqrt(energy/n);m.crest=20*std::log10(m.peak/std::max(1e-12,m.rms));return m;}
double delta(const Audio& dry,const Audio& wet,int rate,double gain){double e=0,d=0;for(size_t i=rate;i<dry[0].size();++i)for(int c=0;c<2;++c){const double x=wet[c][i]*gain-dry[c][i];e+=x*x;d+=double(dry[c][i])*dry[c][i];}return std::sqrt(e/d);}
void wav(const std::filesystem::path& p,const Audio& a,int rate,double gain){std::ofstream f(p,std::ios::binary);auto u16=[&](unsigned v){f.put(char(v));f.put(char(v>>8));};auto u32=[&](unsigned v){u16(v);u16(v>>16);};const unsigned bytes=unsigned(a[0].size()*4);f.write("RIFF",4);u32(36+bytes);f.write("WAVEfmt ",8);u32(16);u16(1);u16(2);u32(rate);u32(rate*4);u16(4);u16(16);f.write("data",4);u32(bytes);for(size_t i=0;i<a[0].size();++i)for(int c=0;c<2;++c)u16(static_cast<unsigned>(static_cast<short>(std::lround(std::clamp(float(a[c][i]*gain),-.999f,.999f)*32767))));}
double thd(bool analog,int rate){masterlab::DynamicsSettings c;c.enabled=true;c.analog=analog;c.ratio=1;masterlab::SmartCompressor d;d.settings(c);d.prepare(rate);std::vector<double> y(rate);std::array<float,257> l{},r{};for(int offset=0;offset<rate*2;offset+=257){const int n=std::min(257,rate*2-offset);for(int i=0;i<n;++i)l[i]=r[i]=.5f*std::sin(6.283185307179586*1000*(offset+i)/rate);d.process(l.data(),r.data(),n);for(int i=0;i<n;++i)if(offset+i>=rate)y[offset+i-rate]=l[i];}auto magnitude=[&](int harmonic){double re=0,im=0;for(int i=0;i<rate;++i){const double phase=6.283185307179586*1000*harmonic*i/rate;re+=y[i]*std::cos(phase);im-=y[i]*std::sin(phase);}return re*re+im*im;};const double fundamental=magnitude(1);double harmonics=0;for(int h=2;h<=8;++h)harmonics+=magnitude(h);return 10*std::log10(std::max(1e-30,harmonics/fundamental));}
int main(int argc,char** argv){if(argc!=2)return 2;const int rate=48000;std::filesystem::path dir=argv[1];std::filesystem::create_directories(dir);const auto input=source(rate);const auto dry=render(input,rate,0),legacy=render(input,rate,1),strong=render(input,rate,2),punch=render(input,rate,3);const auto dm=measure(dry.audio,rate),lm=measure(legacy.audio,rate),sm=measure(strong.audio,rate),pm=measure(punch.audio,rate);std::ostringstream csv;csv<<"render,lufs_raw,peak_raw,crest_db,max_gr_db,max_punch_db,match_gain_db,matched_delta_ratio\n";auto row=[&](const char* name,const Render& x,const Metrics& m){const double gain=std::pow(10.,(dm.lufs-m.lufs)/20);csv<<name<<','<<m.lufs<<','<<m.peak<<','<<m.crest<<','<<x.maxGr<<','<<x.maxPunch<<','<<20*std::log10(gain)<<','<<delta(dry.audio,x.audio,rate,gain)<<'\n';return gain;};csv<<"dry,"<<dm.lufs<<','<<dm.peak<<','<<dm.crest<<",0,0,0,0\n";const auto lg=row("legacy",legacy,lm),sg=row("strong",strong,sm),pg=row("strong_punch",punch,pm);csv<<"digital_thd_db,"<<thd(false,rate)<<"\nanalog_thd_db,"<<thd(true,rate)<<'\n';std::ofstream(dir/"dynamics-metrics.csv")<<csv.str();wav(dir/"dynamics-dry.wav",dry.audio,rate,1);wav(dir/"dynamics-legacy-matched.wav",legacy.audio,rate,lg);wav(dir/"dynamics-strong-matched.wav",strong.audio,rate,sg);wav(dir/"dynamics-strong-punch-matched.wav",punch.audio,rate,pg);std::cout<<csv.str();}
